#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Author this section. Set TOTAL_STAGES to match the stages below.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=12
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
MODE="${1:---help}"
NODE_VERSION="v24.21.0"
case "$(uname -m)" in
  x86_64) NODE_PLATFORM_ARCH="x64" ;;
  aarch64) NODE_PLATFORM_ARCH="arm64" ;;
  *) NODE_PLATFORM_ARCH="unsupported" ;;
esac
NODE_ARCHIVE="node-${NODE_VERSION}-linux-${NODE_PLATFORM_ARCH}"
POSTGRES_CONTAINER="nebula-postgres"
POSTGRES_PORT="5433"

usage() {
  cat <<'EOF'
Usage: scripts/setup_e2e_wizard.sh MODE

Prepare Ubuntu/WSL for Nebula's local PostgreSQL + Anvil E2E workflow.

Modes:
  --check    Inspect prerequisites only; never installs or changes state.
  --plan     Print all stages and commands without running them.
  --install  Interactively install tools and project dependencies.
  --verify   Interactively prepare local services and run the golden E2E twice.
  --help     Show this help.
EOF
}

plan() {
  cat <<'EOF'
Nebula E2E setup plan (12 stages):
  1. Ubuntu/WSL host validation
  2. base operating-system packages
  3. Python 3.12 and uv
  4. Node.js 24 LTS and npm
  5. Foundry, Forge, Cast, and Anvil
  6. Docker Engine, Compose, and PostgreSQL
  7. repository dependencies
  8. Playwright Chromium
  9. local E2E environment
 10. contract build and deployed-artifact validation
 11. optional NVIDIA/CUDA readiness
 12. complete E2E readiness verification

The canonical local E2E uses a deterministic worker fixture. CUDA is optional.
Every privileged download, install, configuration write, container start, and
test execution has its own confirmation gate.
EOF
}

ok() { printf '  OK   %s\n' "$1"; }
missing() { printf '  MISS %s\n' "$1"; CHECK_FAILURES=$((CHECK_FAILURES + 1)); }

check_command() {
  local command_name="$1" label="${2:-$1}"
  if command -v "$command_name" >/dev/null 2>&1; then
    ok "$label: $("$command_name" --version 2>/dev/null | head -n1 || printf available)"
  else
    missing "$label"
  fi
}

check_prerequisites() {
  CHECK_FAILURES=0
  printf 'Nebula E2E prerequisite check (non-mutating)\n'
  if [[ -r /etc/os-release ]] && grep -q '^ID=ubuntu$' /etc/os-release; then ok "Ubuntu host"; else missing "Ubuntu host"; fi
  if grep -qi microsoft /proc/version 2>/dev/null; then ok "WSL"; else ok "native Linux (WSL is not required)"; fi
  check_command git
  check_command curl
  check_command uv
  check_command python3.12
  if command -v node >/dev/null 2>&1 && [[ "$(node --version)" == v24.* ]]; then
    ok "node: $(node --version)"
  else
    missing "node 24 LTS"
  fi
  check_command npm
  check_command forge
  check_command cast
  check_command anvil
  check_command docker
  if command -v docker >/dev/null 2>&1 && docker compose version >/dev/null 2>&1; then
    ok "docker compose: $(docker compose version)"
  else
    missing "docker compose"
  fi
  if command -v docker >/dev/null 2>&1 && docker info >/dev/null 2>&1; then ok "Docker daemon"; else missing "Docker daemon or current-user access"; fi
  [[ -d "$REPO_ROOT/contracts/lib/openzeppelin-contracts" ]] && ok "Foundry dependencies" || missing "Foundry dependencies"
  [[ -x "$REPO_ROOT/backend/.venv/bin/python" ]] && ok "backend virtual environment" || missing "backend virtual environment"
  [[ -x "$REPO_ROOT/worker/.venv/bin/python" ]] && ok "worker virtual environment" || missing "worker virtual environment"
  [[ -d "$REPO_ROOT/frontend/node_modules" ]] && ok "frontend dependencies" || missing "frontend dependencies"
  if command -v nvidia-smi >/dev/null 2>&1; then ok "optional NVIDIA driver"; else printf '  SKIP optional NVIDIA/CUDA (not required for fixture E2E)\n'; fi
  if (( CHECK_FAILURES )); then
    printf '\n%d required prerequisite(s) missing. Run --plan, then --install.\n' "$CHECK_FAILURES"
    return 1
  fi
  printf '\nAll required E2E prerequisites are ready.\n'
}

require_tty() {
  if [[ ! -t 0 || ! -t 1 ]]; then
    printf 'ERROR: %s requires an interactive terminal.\n' "$MODE" >&2
    return 2
  fi
}

run_required() {
  local description="$1"
  shift
  if confirm "$description?"; then
    "$@"
  else
    warn "required stage declined: $description"
    return 1
  fi
}

download_and_run() {
  local label="$1" url="$2" installer
  installer="$(mktemp)"
  curl --proto '=https' --tlsv1.2 -fsSL "$url" -o "$installer"
  say "$label installer downloaded to a temporary file."
  step "Review it now. Press q to leave the viewer."
  "${PAGER:-less}" "$installer"
  if confirm "Run the reviewed $label installer now?"; then bash "$installer"; else SKIPPED+=("$label installer"); fi
  rm -f "$installer"
}

install_node() {
  local archive="${NODE_ARCHIVE}.tar.xz" tmpdir
  [[ "$NODE_PLATFORM_ARCH" != "unsupported" ]] || {
    warn "Unsupported Node.js architecture: $(uname -m)"
    return 1
  }
  tmpdir="$(mktemp -d)"
  curl --proto '=https' --tlsv1.2 -fsSLO "https://nodejs.org/dist/${NODE_VERSION}/$archive" --output-dir "$tmpdir"
  curl --proto '=https' --tlsv1.2 -fsSLO "https://nodejs.org/dist/${NODE_VERSION}/SHASUMS256.txt" --output-dir "$tmpdir"
  (cd "$tmpdir"; grep " $archive$" SHASUMS256.txt | sha256sum --check -)
  mkdir -p "$HOME/.local/lib" "$HOME/.local/bin"
  tar -xJf "$tmpdir/$archive" -C "$HOME/.local/lib"
  ln -sfn "$HOME/.local/lib/$NODE_ARCHIVE/bin/node" "$HOME/.local/bin/node"
  ln -sfn "$HOME/.local/lib/$NODE_ARCHIVE/bin/npm" "$HOME/.local/bin/npm"
  ln -sfn "$HOME/.local/lib/$NODE_ARCHIVE/bin/npx" "$HOME/.local/bin/npx"
  rm -rf "$tmpdir"
  export PATH="$HOME/.local/bin:$PATH"
}

install_docker() {
  local installer
  installer="$(mktemp)"
  curl --proto '=https' --tlsv1.2 -fsSL https://get.docker.com -o "$installer"
  say "Docker's official development installer was downloaded."
  sh "$installer" --dry-run
  if confirm "Run the reviewed Docker installer with sudo?"; then
    sudo sh "$installer"
    sudo usermod -aG docker "$USER"
    warn "Docker group membership takes effect after opening a new WSL shell."
  else
    SKIPPED+=("Docker Engine installation")
  fi
  rm -f "$installer"
}

docker_installation_complete() {
  command -v docker >/dev/null 2>&1 &&
    docker compose version >/dev/null 2>&1 &&
    docker info >/dev/null 2>&1
}

ensure_docker_installation() {
  if ! command -v docker >/dev/null 2>&1 || ! docker compose version >/dev/null 2>&1; then
    install_docker
  elif ! docker info >/dev/null 2>&1; then
    say "Docker CLI and Compose exist, but the daemon is unavailable."
    if command -v service >/dev/null 2>&1; then sudo service docker start || true; fi
  fi
  if ! docker_installation_complete; then
    open_url "https://docs.docker.com/desktop/features/wsl/"
    warn "Docker is not ready for this user. Enable WSL integration or reopen WSL after group setup."
    return 1
  fi
}

install_repository_dependencies() {
  (cd "$REPO_ROOT/backend"; uv sync --all-extras)
  [[ -x "$REPO_ROOT/worker/.venv/bin/python" ]] || \
    uv venv "$REPO_ROOT/worker/.venv" --python 3.12
  uv pip install --python "$REPO_ROOT/worker/.venv/bin/python" -r "$REPO_ROOT/worker/requirements.txt"
  (cd "$REPO_ROOT/frontend"; npm ci)
  (
    cd "$REPO_ROOT/contracts"
    [[ -d lib/openzeppelin-contracts ]] || forge install OpenZeppelin/openzeppelin-contracts@v5.0.2 --no-git
    [[ -f lib/openzeppelin-contracts/lib/forge-std/src/StdInvariant.sol ]] || \
      git clone --branch v1.9.7 --depth 1 https://github.com/foundry-rs/forge-std.git \
        lib/openzeppelin-contracts/lib/forge-std
  )
}

write_local_environment() {
  ENV_FILE="$REPO_ROOT/backend/.env"
  umask 077
  write_env DATABASE_URL "postgresql+asyncpg://nebula:nebula_e2e@127.0.0.1:${POSTGRES_PORT}/nebula"
  write_env JWT_SECRET "local-e2e-only-change-before-any-shared-deployment"
  write_env FRONTEND_URL "http://127.0.0.1:5173"
  write_env STORAGE_ADAPTER "file"
  write_env LOCAL_STORAGE_PATH "/tmp/nebula-e2e-storage"
  chmod 600 "$ENV_FILE"
}

build_artifacts() {
  (cd "$REPO_ROOT/contracts"; forge build)
  "$REPO_ROOT/backend/.venv/bin/python" -c '
import json
from pathlib import Path
root = Path.cwd()
artifact = json.loads((root / "backend/app/nebula_artifact.json").read_text())
manifest = json.loads((root / "contracts/deployments/arbitrum-sepolia.json").read_text())
assert artifact["abi_sha256"] == manifest["abi_sha256"], "backend ABI differs from deployed manifest"
assert artifact["runtime_bytecode_sha256"] == manifest["runtime_template_sha256"], "runtime template differs from deployed manifest"
print("validated backend artifacts against deployed Arbitrum Sepolia manifest")
'
}

ensure_postgres() {
  if docker ps -a --format '{{.Names}}' | grep -qx "$POSTGRES_CONTAINER"; then
    local image host_ip port env_values
    image="$(docker inspect --format '{{.Config.Image}}' "$POSTGRES_CONTAINER")"
    host_ip="$(docker inspect --format '{{(index (index .HostConfig.PortBindings "5432/tcp") 0).HostIp}}' "$POSTGRES_CONTAINER" 2>/dev/null || true)"
    port="$(docker inspect --format '{{(index (index .HostConfig.PortBindings "5432/tcp") 0).HostPort}}' "$POSTGRES_CONTAINER" 2>/dev/null || true)"
    env_values="$(docker inspect --format '{{range .Config.Env}}{{println .}}{{end}}' "$POSTGRES_CONTAINER")"
    [[ "$image" == "postgres:16-alpine" && "$host_ip" == "127.0.0.1" && "$port" == "$POSTGRES_PORT" ]] || {
      warn "Existing $POSTGRES_CONTAINER does not match postgres:16-alpine on 127.0.0.1:$POSTGRES_PORT."
      warn "Rename or remove that container yourself, then rerun --verify."
      return 1
    }
    grep -qx 'POSTGRES_USER=nebula' <<<"$env_values" || { warn "Existing PostgreSQL user does not match."; return 1; }
    grep -qx 'POSTGRES_DB=nebula' <<<"$env_values" || { warn "Existing PostgreSQL database does not match."; return 1; }
    grep -qx 'POSTGRES_PASSWORD=nebula_e2e' <<<"$env_values" || { warn "Existing PostgreSQL password does not match."; return 1; }
    docker start "$POSTGRES_CONTAINER" >/dev/null
  else
    docker run -d --name "$POSTGRES_CONTAINER" \
      -e POSTGRES_USER=nebula -e POSTGRES_PASSWORD=nebula_e2e -e POSTGRES_DB=nebula \
      -p "127.0.0.1:${POSTGRES_PORT}:5432" postgres:16-alpine >/dev/null
  fi
  local attempt
  for attempt in {1..30}; do
    if docker exec "$POSTGRES_CONTAINER" pg_isready -U nebula -d nebula >/dev/null 2>&1; then break; fi
    sleep 1
  done
  docker exec "$POSTGRES_CONTAINER" pg_isready -U nebula -d nebula >/dev/null
  if ! docker exec "$POSTGRES_CONTAINER" psql -U nebula -d postgres -tAc "SELECT 1 FROM pg_database WHERE datname='nebula_test'" | grep -qx 1; then
    docker exec "$POSTGRES_CONTAINER" createdb -U nebula nebula_test
  fi
  (cd "$REPO_ROOT/backend"; DATABASE_URL="postgresql+asyncpg://nebula:nebula_e2e@127.0.0.1:${POSTGRES_PORT}/nebula_test" .venv/bin/alembic upgrade head)
}

run_golden_e2e() {
  local e2e_url="postgresql+asyncpg://nebula:nebula_e2e@127.0.0.1:${POSTGRES_PORT}/nebula_test"
  (cd "$REPO_ROOT"; DATABASE_URL="$e2e_url" backend/.venv/bin/pytest -q backend/tests/test_integration_closure_e2e.py)
  (cd "$REPO_ROOT"; DATABASE_URL="$e2e_url" backend/.venv/bin/pytest -q backend/tests/test_integration_closure_e2e.py)
}

check_optional_cuda() {
  if ! command -v nvidia-smi >/dev/null 2>&1; then
    open_url "https://docs.nvidia.com/cuda/wsl-user-guide/index.html"
    warn "NVIDIA WSL passthrough is unavailable; follow the official Windows-driver setup."
    return 1
  fi
  nvidia-smi
  if [[ -x "$REPO_ROOT/worker/.venv/bin/python" ]]; then
    "$REPO_ROOT/worker/.venv/bin/python" -c \
      'import torch; assert torch.cuda.is_available(), "PyTorch cannot access CUDA"; print(torch.cuda.get_device_name(0))'
  else
    warn "Install worker dependencies before checking torch.cuda.is_available()."
    return 1
  fi
}

run_optional_browser_e2e() {
  local BE002_FRONTEND_ORIGIN=""
  say "The browser-auth smoke requires an already deployed HTTPS frontend origin."
  ask BE002_FRONTEND_ORIGIN "Deployed frontend origin (Enter to skip):"
  if [[ -z "$BE002_FRONTEND_ORIGIN" ]]; then
    SKIPPED+=("deployed browser-auth smoke")
    return 0
  fi
  (cd "$REPO_ROOT/frontend"; BE002_FRONTEND_ORIGIN="$BE002_FRONTEND_ORIGIN" npm run test:browser-auth)
}

verify_playwright_browser() {
  (
    cd "$REPO_ROOT/frontend"
    node --input-type=module -e \
      "import { chromium } from '@playwright/test'; const browser = await chromium.launch({headless:true}); const page = await browser.newPage(); await page.setContent('<title>nebula-e2e-ready</title>'); if ((await page.title()) !== 'nebula-e2e-ready') process.exit(1); await browser.close();"
  )
}

install_wizard() {
  banner "Nebula Ubuntu/WSL E2E setup"

  stage "Ubuntu/WSL host validation"
  grep -q '^ID=ubuntu$' /etc/os-release || { warn "Only Ubuntu is supported."; return 1; }
  say "Detected $(. /etc/os-release; printf '%s' "$PRETTY_NAME") on $(uname -m)."

  stage "base operating-system packages"
  run_required "Update apt package metadata" sudo apt-get update
  run_required "Install required apt packages" sudo apt-get install -y build-essential ca-certificates curl git jq pkg-config libssl-dev libffi-dev python3-dev xz-utils postgresql-client shellcheck

  stage "Python 3.12 and uv"
  open_url "https://docs.astral.sh/uv/getting-started/installation/"
  command -v uv >/dev/null 2>&1 || download_and_run "uv" "https://astral.sh/uv/install.sh"
  export PATH="$HOME/.local/bin:$HOME/.cargo/bin:$PATH"
  run_required "Install managed Python 3.12 with uv" uv python install 3.12

  stage "Node.js 24 LTS and npm"
  open_url "https://nodejs.org/en/download"
  run_required "Install SHA-256-verified Node.js $NODE_VERSION under ~/.local" install_node

  stage "Foundry, Forge, Cast, and Anvil"
  open_url "https://getfoundry.sh/getting-started/installation"
  command -v foundryup >/dev/null 2>&1 || download_and_run "Foundryup" "https://foundry.paradigm.xyz"
  export PATH="$HOME/.foundry/bin:$PATH"
  run_required "Install the latest stable Foundry toolchain" foundryup

  stage "Docker Engine, Compose, and PostgreSQL"
  open_url "https://docs.docker.com/engine/install/ubuntu/"
  docker_installation_complete || run_required "Docker installation or repair" ensure_docker_installation
  say "PostgreSQL 16 will be isolated on 127.0.0.1:$POSTGRES_PORT during --verify."

  stage "repository dependencies"
  run_required "Install backend, worker, frontend, and contract dependencies" install_repository_dependencies

  stage "Playwright Chromium"
  open_url "https://playwright.dev/docs/browsers"
  run_required "Install Playwright Chromium and Ubuntu dependencies" bash -c "cd '$REPO_ROOT/frontend' && npx playwright install --with-deps chromium"

  stage "local E2E environment"
  run_required "Write ignored local test values to backend/.env" write_local_environment

  stage "contract build and deployed-artifact validation"
  run_required "Build contracts and validate deployed backend artifacts" build_artifacts

  stage "optional NVIDIA/CUDA readiness"
  if confirm "Check optional NVIDIA/WSL GPU passthrough now?"; then
    check_optional_cuda || warn "CUDA remains optional for the fixture E2E."
  else
    SKIPPED+=("optional NVIDIA/CUDA readiness")
  fi

  stage "complete E2E readiness verification"
  say "Reopen WSL if PATH or Docker group membership changed."
  step "Run ./scripts/setup_e2e_wizard.sh --check"
  step "Then run ./scripts/setup_e2e_wizard.sh --verify"
  finish
}

verify_wizard() {
  banner "Nebula E2E verification"

  stage "Ubuntu/WSL host validation"
  check_prerequisites || { warn "Finish --install and reopen WSL first."; return 1; }
  stage "base operating-system packages"; ok "covered by prerequisite check"
  stage "Python 3.12 and uv"; uv run --python 3.12 python --version
  stage "Node.js 24 LTS and npm"; node --version; npm --version
  stage "Foundry, Forge, Cast, and Anvil"; forge --version; anvil --version
  stage "Docker Engine, Compose, and PostgreSQL"
  run_required "Start/provision isolated PostgreSQL and migrate nebula_test" ensure_postgres
  stage "repository dependencies"; ok "dependency directories detected"
  stage "Playwright Chromium"
  run_required "Launch Playwright Chromium for a readiness smoke" verify_playwright_browser
  run_optional_browser_e2e
  stage "local E2E environment"
  [[ -f "$REPO_ROOT/backend/.env" ]] || { warn "backend/.env is missing."; return 1; }
  ok "backend/.env exists"
  stage "contract build and deployed-artifact validation"
  run_required "Run Forge build and deployed-artifact validation" build_artifacts
  stage "optional NVIDIA/CUDA readiness"
  check_optional_cuda || say "Skipped: fixture E2E does not require CUDA."
  stage "complete E2E readiness verification"
  run_required "Run the authoritative four-journey E2E suite twice" run_golden_e2e
  finish
}

case "$MODE" in
  --help|-h) usage ;;
  --plan) plan ;;
  --check) check_prerequisites ;;
  --install) require_tty || exit $?; install_wizard ;;
  --verify) require_tty || exit $?; verify_wizard ;;
  *) printf 'ERROR: unknown mode: %s\n\n' "$MODE" >&2; usage >&2; exit 2 ;;
esac

